package br.com.brindespro.portfolio;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.HttpStatus;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.time.OffsetDateTime;import java.util.*;
@RestController @RequestMapping("/api") public class PortfolioController {private final PortfolioProjectRepository projects;private final PortfolioTestimonialRepository testimonials;public PortfolioController(PortfolioProjectRepository projects,PortfolioTestimonialRepository testimonials){this.projects=projects;this.testimonials=testimonials;}public record ProjectDto(Long id,String name,String segment,String category,String description,int quantity,String leadTime,String finishType,String imageUrl,boolean featured,boolean active){}public record TestimonialDto(Long id,Long projectId,String personName,String role,String company,String segment,String message){}public record ProjectInput(@NotBlank String name,@NotBlank String segment,@NotBlank String category,@NotBlank String description,@Min(1) int quantity,@NotBlank String leadTime,@NotBlank String finishType,@NotBlank String imageUrl,boolean featured,boolean active){}private ProjectDto dto(PortfolioProject p){return new ProjectDto(p.id,p.name,p.segment,p.category,p.description,p.quantity,p.leadTime,p.finishType,p.imageUrl,p.featured,p.active);}private TestimonialDto testimonial(PortfolioTestimonial t){return new TestimonialDto(t.id,t.project==null?null:t.project.id,t.personName,t.role,t.company,t.segment,t.message);}@GetMapping("/portfolio") public List<ProjectDto> list(@RequestParam(defaultValue="") String segment){return (segment.isBlank()||segment.equalsIgnoreCase("Todos")?projects.findByActiveTrueOrderByFeaturedDescCreatedAtDesc():projects.findByActiveTrueAndSegmentIgnoreCaseOrderByFeaturedDescCreatedAtDesc(segment)).stream().map(this::dto).toList();}@GetMapping("/portfolio/featured") public List<ProjectDto> featured(){return projects.findByActiveTrueAndFeaturedTrueOrderByCreatedAtDesc().stream().limit(3).map(this::dto).toList();}@GetMapping("/portfolio/testimonials") public List<TestimonialDto> testimonials(){return testimonials.findByActiveTrue().stream().map(this::testimonial).toList();}@GetMapping("/admin/portfolio") public List<ProjectDto> adminList(){return projects.findAll().stream().map(this::dto).toList();}@PostMapping("/admin/portfolio") @ResponseStatus(HttpStatus.CREATED) public ProjectDto create(@Valid @RequestBody ProjectInput input,Authentication auth){return dto(save(new PortfolioProject(),input));}@PutMapping("/admin/portfolio/{id}") public ProjectDto update(@PathVariable Long id,@Valid @RequestBody ProjectInput input,Authentication auth){return dto(save(projects.findById(id).orElseThrow(()->new NoSuchElementException("Projeto não encontrado.")),input));}@DeleteMapping("/admin/portfolio/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id,Authentication auth){projects.delete(projects.findById(id).orElseThrow(()->new NoSuchElementException("Projeto não encontrado.")));}private PortfolioProject save(PortfolioProject p,ProjectInput i){p.name=i.name();p.segment=i.segment();p.category=i.category();p.description=i.description();p.quantity=i.quantity();p.leadTime=i.leadTime();p.finishType=i.finishType();p.imageUrl=i.imageUrl();p.featured=i.featured();p.active=i.active();p.updatedAt=OffsetDateTime.now();return projects.save(p);}}
